const listAltNumbersForParts = `-- name: ListAltNumbersForParts :many
SELECT part_id, scheme, alt_ref FROM alt_numbering
WHERE part_id IN (/*SLICE:part_ids*/?)
ORDER BY part_id, scheme, provider
`

type ListAltNumbersForPartsRow struct {
	PartID int64
	Scheme string
	AltRef string
}

// Every other number of a page of parts, one per scheme: the first provider's.
func (q *Queries) ListAltNumbersForParts(ctx context.Context, partIds []int64) ([]ListAltNumbersForPartsRow, error) {
	query := listAltNumbersForParts
	var queryParams []interface{}
	if len(partIds) > 0 {
		for _, v := range partIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:part_ids*/?", strings.Repeat(",?", len(partIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:part_ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAltNumbersForPartsRow{}
	for rows.Next() {
		var i ListAltNumbersForPartsRow
		if err := rows.Scan(&i.PartID, &i.Scheme, &i.AltRef); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listCalendarEntries = `-- name: ListCalendarEntries :many
SELECT w.id, w.canonical_title, w.sort_title, w.subtype,
       COALESCE(pa.name, '') AS artist_name,
       MIN(wd.date) AS release_date,
       EXISTS (SELECT 1 FROM work_file wf WHERE wf.work_id = w.id) AS on_disk
FROM work_date wd
JOIN work w ON w.id = wd.work_id
LEFT JOIN person pa ON pa.id = w.lead_person_id
WHERE wd.kind = ?1
  AND wd.date >= ?2 AND wd.date <= ?3
  AND (
    EXISTS (SELECT 1 FROM desired_item di WHERE di.work_id = w.id AND di.monitored = 1
            AND di.category_id IN (SELECT value FROM json_each(?4)))
    OR EXISTS (SELECT 1 FROM credit c
               JOIN person p ON p.id = c.person_id
               JOIN subscription s ON s.subject_type = 'person' AND s.subject_id = p.id AND s.enabled = 1
               WHERE c.work_id = w.id AND c.role = 'artist' AND p.monitored = 1
                 AND s.category_id IN (SELECT value FROM json_each(?4)))
  )
GROUP BY w.id
ORDER BY release_date, w.sort_title, w.id
LIMIT ?5
`

type ListCalendarEntriesParams struct {
	Kind        string
	FromDate    string
	ToDate      string
	CategoryIds interface{}
	PageSize    int64
}

type ListCalendarEntriesRow struct {
	ID             int64
	CanonicalTitle string
	SortTitle      string
	Subtype        sql.NullString
	ArtistName     string
	ReleaseDate    interface{}
	OnDisk         bool
}

// Releases in a date window that this library has a reason to care about:
// either something wants the work, or an artist credited on it is monitored.
// A work with several dates of the same kind in different regions would repeat,
// so the earliest per work is taken -- a calendar shows one entry per release.
// Only libraries the caller can see: a wanted work through its desired_item, a followed artist's
// release through the subscription that follows them.
func (q *Queries) ListCalendarEntries(ctx context.Context, arg ListCalendarEntriesParams) ([]ListCalendarEntriesRow, error) {
	rows, err := q.db.QueryContext(ctx, listCalendarEntries,
		arg.Kind,
		arg.FromDate,
		arg.ToDate,
		arg.CategoryIds,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCalendarEntriesRow{}
	for rows.Next() {
		var i ListCalendarEntriesRow
		if err := rows.Scan(
			&i.ID,
			&i.CanonicalTitle,
			&i.SortTitle,
			&i.Subtype,
			&i.ArtistName,
			&i.ReleaseDate,
			&i.OnDisk,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

